/**
 * Transcribe a MATPOWER .m case file into the TypeScript data module the app
 * uses. Run manually when a case is added; the generated file is committed so
 * the app has no build-time dependency on MATPOWER.
 *
 *   node tools/gen-ieee-case.mjs <case.m> <exportName> <id> <displayName> <source> > src/data/<file>.ts
 */
import { readFileSync } from 'node:fs';

const [, , file, exportName, id, displayName, source] = process.argv;
const text = readFileSync(file, 'utf8');

function section(name) {
  const re = new RegExp(`mpc\\.${name}\\s*=\\s*\\[([\\s\\S]*?)\\];`, 'm');
  const m = text.match(re);
  if (!m) throw new Error(`section ${name} not found`);
  return m[1]
    .split('\n')
    .map((l) => l.replace(/%.*$/, '').trim())
    .filter((l) => l.length > 0)
    .map((l) => l.replace(/;$/, '').trim().split(/\s+/).map(Number));
}

const baseMVA = Number(text.match(/mpc\.baseMVA\s*=\s*([\d.]+)/)[1]);
const bus = section('bus').map((r) => r.slice(0, 13));
const gen = section('gen').map((r) => r.slice(0, 10));
const branch = section('branch').map((r) => r.slice(0, 11));

const fmt = (rows) =>
  rows.map((r) => `    [${r.map((v) => String(v)).join(', ')}],`).join('\n');

const voltages = bus.map((r) => `[${r[7]}, ${r[8]}]`);
const chunked = [];
for (let i = 0; i < voltages.length; i += 5) chunked.push('      ' + voltages.slice(i, i + 5).join(', ') + ',');

process.stdout.write(`/**
 * ${displayName} test system.
 *
 * GENERATED by tools/gen-ieee-case.mjs from the authoritative case file — do
 * not hand-edit. Source: ${source}
 *
 * Used to validate the power-flow solver. The Vm/Va columns of the published
 * bus table hold the CONVERGED solution rather than a starting guess, so they
 * are lifted into \`reference\` below and the solver is started flat, which
 * makes the comparison meaningful.
 */

import { MatpowerCase } from './matpower.js';

export const ${exportName}: MatpowerCase = {
  id: '${id}',
  name: '${displayName}',
  baseMVA: ${baseMVA},
  source: '${source}',
  //     bus_i type Pd Qd Gs Bs area Vm Va baseKV zone Vmax Vmin
  bus: [
${fmt(bus)}
  ],
  //     bus Pg Qg Qmax Qmin Vg mBase status Pmax Pmin
  gen: [
${fmt(gen)}
  ],
  //     fbus tbus r x b rateA rateB rateC ratio angle status
  branch: [
${fmt(branch)}
  ],
  reference: {
    note:
      'Converged solution as published in the case file bus table, |V| to 3 ' +
      'decimal places and θ to 2 decimal places. Generator reactive limits are ' +
      'NOT enforced, matching the conditions of the published run.',
    voltages: [
${chunked.join('\n')}
    ],
  },
};
`);
